import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"ADOFAIMacro","description":"","frontmatter":{"title":"ADOFAIMacro","order":13},"headers":[],"relativePath":"zh/mods/adofai-macro.md","filePath":"zh/mods/adofai-macro.md","lastUpdated":1786943111000}'),r={name:"zh/mods/adofai-macro.md"};function c(l,e,i,s,n,u){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="adofaimacro" tabindex="-1">ADOFAIMacro <a class="header-anchor" href="#adofaimacro" aria-label="Permalink to &quot;ADOFAIMacro&quot;">​</a></h1><blockquote><p>用于《冰与火之舞》的 UnityModManager（UMM）模组，提供更<strong>稳定、可调、可过滤</strong>的自动输入能力，覆盖从「直接判定触发」到「系统级按键模拟」的多种场景。</p><p>项目地址：<a href="https://github.com/adofaiex/ADOFAIMacro" target="_blank" rel="noreferrer">https://github.com/adofaiex/ADOFAIMacro</a></p></blockquote><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h2><ul><li><strong>自动触发</strong>：解析谱面地板时间戳，工作线程高精度定时发送按键</li><li><strong>触发模式</strong>： <ul><li><strong>判定触发</strong>（<code>SimulateKeyPress = false</code>）：工作线程计数 → 主线程 <code>controller.Hit()</code></li><li><strong>按键模拟</strong>（<code>SimulateKeyPress = true</code>）：工作线程调用 <code>SendKey()</code> 模拟系统级按键</li></ul></li><li><strong>宏按键模式</strong>： <ul><li><strong>简单轮转</strong>（<code>EnableTechniqueSimulation = false</code>）：<code>MacroKeys</code> 列表循环，带 <code>_pendingKey</code> 防重叠</li><li><strong>手法模拟</strong>（<code>EnableTechniqueSimulation = true</code>）：左右手交替、可配置按键与顺序、BPM 分片、长按处理、同键修正</li></ul></li><li><strong>关卡特定手法配置</strong>：为不同关卡保存独立的手法参数，进入自动加载；支持按 floor 区间覆盖设置</li><li><strong>时间偏移微调</strong>：毫秒级偏移，游戏中 <code>Ctrl + 左右键</code> / <code>左右键</code> 实时调参</li><li><strong>按键过滤系统</strong>：黑白名单模式，同步（KeyCode 位图）与异步（VK 码数组）独立过滤</li><li><strong>SkyHook 异步输入</strong>：<code>NtUserInjectKeyboard</code> 等底层注入路径，适合高频 / 复杂环境</li><li><strong>死亡后自动按键（Death Key）</strong>：可配置死亡后按键与触发延迟（仅 SkyHook 模式生效）</li><li><strong>多语言 UI</strong>：中文 / English</li></ul><h2 id="工作模式" tabindex="-1">工作模式 <a class="header-anchor" href="#工作模式" aria-label="Permalink to &quot;工作模式&quot;">​</a></h2><h3 id="直接-hit-模式-simulatekeypress-false" tabindex="-1">直接 Hit 模式（<code>SimulateKeyPress = false</code>） <a class="header-anchor" href="#直接-hit-模式-simulatekeypress-false" aria-label="Permalink to &quot;直接 Hit 模式（`SimulateKeyPress = false`）&quot;">​</a></h3><p>宏触发时直接命中游戏逻辑。链路短、延迟可控，适合纯宏判定场景。</p><h3 id="按键模拟模式-simulatekeypress-true" tabindex="-1">按键模拟模式（<code>SimulateKeyPress = true</code>） <a class="header-anchor" href="#按键模拟模式-simulatekeypress-true" aria-label="Permalink to &quot;按键模拟模式（`SimulateKeyPress = true`）&quot;">​</a></h3><p>把宏触发转换为系统层按键输入，可选：</p><ul><li><strong>SendInput 路径</strong>（兼容性优先）</li><li><strong>SkyHook 路径</strong>（更偏底层，适合复杂 / 高频环境）</li></ul><h3 id="skyhook-inputmode" tabindex="-1">SkyHook + InputMode <a class="header-anchor" href="#skyhook-inputmode" aria-label="Permalink to &quot;SkyHook + InputMode&quot;">​</a></h3><p><code>SkyHookMode = true</code> 时可选择输入模式：<code>Auto</code>（自动选择）、<code>NtUserInjectKeyboard</code>（底层注入）、<code>NtUserSendInput</code>（中间路径）、<code>SendInput</code>（标准方式，兼容性最好）。建议从 <code>Auto</code> 开始，遇冲突再逐项切换。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h3><ul><li>已安装并可正常运行 UnityModManager</li><li>ADOFAI 可通过 UMM 加载模组</li></ul><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>编译项目得到 <code>ADOFAIMacro.dll</code>（及相关依赖）</li><li>在 <code>Mods/ADOFAIMacro</code> 目录放入： <ul><li><code>ADOFAIMacro.dll</code></li><li><code>Newtonsoft.Json.dll</code>（若游戏目录没有）</li><li><code>Localization/</code> 文件夹（含 <code>zh-CN.json</code>、<code>en-US.json</code>）</li><li>原生 DLL（如 <code>InputSystem.dll</code>、<code>TechniqueSimulator.dll</code>）</li></ul></li><li>启动游戏，在 UMM 面板中启用 <code>ADOFAIMacro</code></li></ol><h2 id="设置项" tabindex="-1">设置项 <a class="header-anchor" href="#设置项" aria-label="Permalink to &quot;设置项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><code>Macro</code></td><td>宏总开关</td></tr><tr><td><code>MacroKeys</code></td><td>宏按键序列，英文逗号分隔（如 <code>D,F,J,K</code>）</td></tr><tr><td><code>SimulateKeyPress</code></td><td>是否用系统按键模拟替代直接 Hit</td></tr><tr><td><code>SkyHookMode</code></td><td>按键模拟时是否使用 SkyHook 路径</td></tr><tr><td><code>InputMode</code></td><td>Auto / NtInject / NtSendInput / SendInput</td></tr><tr><td><code>TimeOffset</code></td><td>宏触发时间偏移（-100 ~ 100 ms）</td></tr><tr><td><code>EnableKeyAdjust</code></td><td>允许游戏中 <code>Ctrl + 方向键</code> 调整</td></tr><tr><td><code>AdjustStep</code></td><td>每次热键调整步长（0.1 ~ 10）</td></tr><tr><td><code>EnableArrowTimeAdjust</code></td><td>允许左右键快速调整延迟</td></tr><tr><td><code>HighPrecisionAsync</code></td><td>实验性高精度异步开关</td></tr><tr><td><code>EnableDeathKey</code> / <code>DeathKeyDelay</code> / <code>DeathKeyInput</code></td><td>死亡后自动按键（需 SkyHook 模式）</td></tr><tr><td><code>EnableKeyFilter</code> / <code>FilterMode</code> / <code>FilteredKeys</code> / <code>FilteredAsyncKeys</code></td><td>按键过滤（0=黑名单，1=白名单）</td></tr></tbody></table><p>按键字符串支持 <code>A-Z</code>、<code>0-9</code>、<code>F1-F12</code>、<code>SPACE</code>、<code>ENTER</code>、<code>ESC</code>、<code>CTRL</code>、<code>ALT</code>、方向键以及十六进制虚拟键码（如 <code>0x41</code>）。</p><h2 id="运行时快捷键" tabindex="-1">运行时快捷键 <a class="header-anchor" href="#运行时快捷键" aria-label="Permalink to &quot;运行时快捷键&quot;">​</a></h2><ul><li><strong>Ctrl + 左/右方向键</strong>：按 <code>AdjustStep</code> 调整偏移</li><li><strong>左右方向键</strong>：直接微调延迟（受 <code>EnableArrowTimeAdjust</code> 控制）</li></ul><h2 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>追求稳定（入门）</td><td><code>SimulateKeyPress = false</code>，<code>TimeOffset = 0</code> 起步，逐步微调</td></tr><tr><td>追求兼容（多软件并行）</td><td><code>SimulateKeyPress = true</code>、<code>SkyHookMode = false</code>、SendInput 路径，必要时开 <code>EnableKeyFilter</code></td></tr><tr><td>高频场景（进阶）</td><td><code>SimulateKeyPress = true</code>、<code>SkyHookMode = true</code>、<code>InputMode = Auto</code> 起步，再微调 <code>TimeOffset</code> 与 <code>AdjustStep</code></td></tr></tbody></table><h2 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to &quot;疑难解答&quot;">​</a></h2><ul><li><strong>宏开了但没反应？</strong> 依次检查：UMM 中已启用、<code>Macro</code> 打开、<code>MacroKeys</code> 格式正确、必要时切换 <code>SkyHookMode</code> / <code>InputMode</code></li><li><strong>有时触发、有时漏键？</strong> 调整 <code>TimeOffset</code>（每次 1ms 微调）；高频场景尝试 <code>SkyHookMode</code>；开启 <code>EnableKeyFilter</code> 屏蔽冲突</li><li><strong>死亡后按键不生效？</strong> 确认 <code>SkyHookMode</code> 已开启、<code>EnableDeathKey</code> 启用、<code>DeathKeyInput</code> 是有效按键名或键码</li></ul>',26)])])}const y=o(r,[["render",c]]);export{m as __pageData,y as default};
